// ========== CONFIGURATION ==========
const CONFIG = {
  BATCH_NUMBER: 0,
  HEADER_SCORE_THRESHOLD: 5,
  FULL_SCORE_THRESHOLD: 6.5,
  MAX_ARTICLE_AGE_HOURS: 48,
  CLASSIFICATION_BATCH_SIZE: 30,
  HEADER_MODEL: 'openai/gpt-5.4-nano',
  SCORING_MODEL: 'openai/gpt-5.4-mini',
};

return [{ json: CONFIG }];

const config = $('Config').first().json;
const feeds = $input.all();

let filtered;
if (config.BATCH_NUMBER === -1) {
  // Poll all feeds
  filtered = feeds;
} else {
  // Poll only the specified batch
  filtered = feeds.filter(f => f.json.batch_number === config.BATCH_NUMBER);
}

if (filtered.length === 0) {
  throw new Error('No active feeds found for batch ' + config.BATCH_NUMBER);
}

return filtered;

// Attach feed metadata to each RSS item
const feedData = $('Loop Feeds').first().json;
const config = $('Config').first().json;
const items = $input.all();
const now = new Date();
const maxAge = config.MAX_ARTICLE_AGE_HOURS * 60 * 60 * 1000;

const results = [];
for (const item of items) {
  // Skip error items from failed RSS reads
  if (item.json.error) continue;

  const pubDate = new Date(item.json.isoDate || item.json.pubDate || now);
  const age = now - pubDate;

  // Skip articles older than MAX_ARTICLE_AGE_HOURS
  if (age > maxAge) continue;

  results.push({
    json: {
      title: item.json.title || '',
      description: item.json.contentSnippet || item.json.content || '',
      url: item.json.link || item.json.guid || '',
      pubDate: item.json.isoDate || item.json.pubDate || now.toISOString(),
      feed_id: feedData.id,
      feed_name: feedData.name,
      feed_category: feedData.category,
      feed_url: feedData.url
    }
  });
}

// Always return at least one item so the loop continues
if (results.length === 0) {
  return [{ json: { _skip: true, feed_name: feedData.name } }];
}

return results;

// Collect all headers from all feeds
const allItems = $('Attach Feed Info').all();

// Filter out skip markers and empty items
const headers = allItems.filter(item => !item.json._skip && item.json.title);

if (headers.length === 0) {
  throw new Error('No articles found from any feed. All feeds may be down or empty.');
}

return [{
  json: {
    total_headers: headers.length,
    headers: headers.map(h => h.json)
  }
}];

// Get existing URLs from Supabase
const existingItems = $('Get Existing URLs').all();
const existingUrls = new Set(
  existingItems.map(item => item.json.url).filter(Boolean)
);

const allHeaders = $('Merge All Headers').first().json.headers;

// Filter out already-seen URLs
const newHeaders = allHeaders.filter(h => !existingUrls.has(h.url));

return [{
  json: {
    total_new: newHeaders.length,
    total_skipped: allHeaders.length - newHeaders.length,
    headers: newHeaders
  }
}];

const config = $('Config').first().json;
const data = $input.first().json;
const headers = data.headers;
const batchSize = config.CLASSIFICATION_BATCH_SIZE;

// Split into batches for LLM classification
const batches = [];
for (let i = 0; i < headers.length; i += batchSize) {
  batches.push({
    json: {
      batch_index: Math.floor(i / batchSize),
      batch_size: Math.min(batchSize, headers.length - i),
      headlines: headers.slice(i, i + batchSize),
      model: config.HEADER_MODEL,
      openrouter_key: config.OPENROUTER_KEY
    }
  });
}

if (batches.length === 0) {
  return [{json: {classified: [], total: 0}}];
}

return batches;

const batch = $json;
const headlines = batch.headlines;

const headlineList = headlines.map(function(h, i) {
  var title = (h.title || '').replace(/"/g, "'").substring(0, 150);
  var desc = (h.description || '').replace(/"/g, "'").substring(0, 200);
  return (i+1) + '. "' + title + '" -- ' + desc;
}).join('\n');

var prompt = 'Classify these news headlines for Brett Moore podcast Fasten Your Seatbelt. ';
prompt += 'Brett covers geopolitics, science/tech, economics, and quirky/surprising stories.\n\n';
prompt += 'For each headline return a JSON array. Each item must have:\n';
prompt += '- index: headline number (1-based)\n';
prompt += '- category: one of [politics, science, tech, economics, quirky, other]\n';
prompt += '- relevance: 1-10 how relevant to Brett\n';
prompt += '- tags: object with keys entities (people/orgs/places), topics (themes), events (what happened)\n';
prompt += '- extract: true if worth reading full article, false to skip\n';
prompt += '- confidence: 0-1 how sure you are\n\n';
prompt += 'Headlines:\n' + headlineList + '\n\nReturn ONLY the JSON array.';

return [{
  json: {
    ...batch,
    classify_prompt: prompt
  }
}];

// Parse LLM classification response
const response = $input.first().json;
const batchData = $('Build Classify Request').item.json;
const headlines = batchData.headlines;

let classified = [];
try {
  const content = response.choices?.[0]?.message?.content || '[]';
  // Extract JSON from response (might have markdown code fences)
  const jsonMatch = content.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    classified = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  // If parsing fails, mark all as extract-worthy to be safe
  classified = headlines.map((h, i) => ({
    index: i + 1, category: 'other', relevance: 5,
    tags: {entities: [], topics: [], events: []},
    extract: true, confidence: 0
  }));
}

// Merge classification with headline data
const results = headlines.map((h, i) => {
  const cls = classified.find(c => c.index === i + 1) || classified[i] || {
    category: 'other', relevance: 5, tags: {entities: [], topics: [], events: []}, extract: true, confidence: 0
  };

  return {
    ...h,
    category: cls.category || h.feed_category || 'other',
    header_score: cls.relevance || 5,
    tags: cls.tags || {entities: [], topics: [], events: []},
    extract_worthy: cls.extract !== false,
    confidence: cls.confidence || 0,
    status: cls.extract !== false ? 'extract_worthy' : 'header_scored'
  };
});

return results.map(r => ({json: r}));

// All classified articles arrive here after the loop
const config = $('Config').first().json;
const allArticles = $('Parse Classifications').all().map(i => i.json);

// ---- CLUSTERING BY TAGS ----
// Group articles sharing entity+event tags within same timeframe
const clusters = {};
let clusterCounter = 0;

for (let i = 0; i < allArticles.length; i++) {
  const a = allArticles[i];
  const aEntities = (a.tags?.entities || []).map(t => t.toLowerCase());
  const aEvents = (a.tags?.events || []).map(t => t.toLowerCase());
  const aTags = [...aEntities, ...aEvents];

  let foundCluster = null;

  for (const [cId, cluster] of Object.entries(clusters)) {
    const cTags = cluster.tags;
    // Match: 1 shared entity + 1 shared event, or 3+ shared tags total
    const shared = aTags.filter(t => cTags.includes(t));
    const sharedEntities = aEntities.filter(t => cluster.entities.includes(t));
    const sharedEvents = aEvents.filter(t => cluster.events.includes(t));

    if ((sharedEntities.length >= 1 && sharedEvents.length >= 1) || shared.length >= 3) {
      foundCluster = cId;
      break;
    }
  }

  if (foundCluster) {
    clusters[foundCluster].articles.push(i);
    clusters[foundCluster].tags = [...new Set([...clusters[foundCluster].tags, ...aTags])];
    clusters[foundCluster].entities = [...new Set([...clusters[foundCluster].entities, ...aEntities])];
    clusters[foundCluster].events = [...new Set([...clusters[foundCluster].events, ...aEvents])];
  } else {
    const cId = 'cluster_' + (clusterCounter++);
    clusters[cId] = {
      articles: [i],
      tags: aTags,
      entities: aEntities,
      events: aEvents
    };
  }
}

// Assign cluster info to each article
for (const [cId, cluster] of Object.entries(clusters)) {
  const sorted = cluster.articles.sort((a, b) => 
    (allArticles[b].header_score || 0) - (allArticles[a].header_score || 0)
  );
  sorted.forEach((idx, rank) => {
    allArticles[idx].cluster_id = cId;
    allArticles[idx].cluster_rank = rank + 1;
    allArticles[idx].source_count = cluster.articles.length;
  });
}

// Filter: only extract primary sources (rank=1) with extract_worthy=true
// and header_score >= threshold
const toExtract = allArticles.filter(a => 
  a.cluster_rank === 1 && 
  a.extract_worthy && 
  (a.header_score || 0) >= config.HEADER_SCORE_THRESHOLD
);

// Stats
const trending = Object.entries(clusters)
  .filter(([_, c]) => c.articles.length >= 3)
  .map(([cId, c]) => ({
    cluster_id: cId,
    source_count: c.articles.length,
    tags: c.tags.slice(0, 5)
  }));

return [{
  json: {
    total_classified: allArticles.length,
    total_clusters: Object.keys(clusters).length,
    total_trending: trending.length,
    total_to_extract: toExtract.length,
    trending,
    all_articles: allArticles,
    to_extract: toExtract
  }
}];

// Save all classified headers to Supabase via REST API
const data = $input.first().json;
const articles = data.all_articles;

// Prepare items for Supabase insert
const rows = articles.map(a => ({
  url: a.url,
  title: (a.title || '').substring(0, 500),
  source_name: a.feed_name || 'RSS',
  source_type: 'rss',
  category: a.category || 'other',
  published_at: a.pubDate || new Date().toISOString(),
  header_score: a.header_score || 0,
  source_count: a.source_count || 1,
  status: a.status || 'header_scored',
  metadata: JSON.stringify({
    tags: a.tags,
    cluster_id: a.cluster_id,
    cluster_rank: a.cluster_rank,
    confidence: a.confidence,
    feed_id: a.feed_id,
    description: (a.description || '').substring(0, 1000),
    extract_worthy: a.extract_worthy
  })
}));

// Return items for downstream + pass through extract list
return [{
  json: {
    saved_count: rows.length,
    to_extract: data.to_extract,
    trending: data.trending,
    save_rows: rows
  }
}];

const data = $('Prepare Bulk Save').first().json;
const toExtract = data.to_extract || [];
const trending = data.trending || [];

if (toExtract.length === 0) {
  return [{json: {_done: true, message: 'No articles to extract', trending}}];
}

// Return each article as a separate item for the extraction loop
return toExtract.map(a => ({
  json: {
    url: a.url,
    title: a.title,
    category: a.category,
    header_score: a.header_score,
    source_count: a.source_count,
    cluster_id: a.cluster_id,
    tags: a.tags,
    feed_name: a.feed_name,
    trending
  }
}));

const llmResponse = $json.text || '{}';
const articleData = $('Loop Extract').item.json;

let scores;
try {
  const jsonMatch = llmResponse.match(/\{[\s\S]*\}/);
  scores = jsonMatch ? JSON.parse(jsonMatch[0]) : {};
} catch(e) {
  scores = {relevance_score: 5, novelty_score: 5, cross_domain_score: 5, 
            storytelling_score: 5, controversy_score: 5, composite_score: 5,
            score_reason: 'Parse error', score_category: articleData.category};
}

return [{
  json: {
    url: articleData.url,
    title: articleData.title,
    content: ($json.data?.content || '').substring(0, 10000),
    category: scores.score_category || articleData.category,
    relevance_score: scores.relevance_score || 5,
    novelty_score: scores.novelty_score || 5,
    cross_domain_score: scores.cross_domain_score || 5,
    storytelling_score: scores.storytelling_score || 5,
    controversy_score: scores.controversy_score || 5,
    composite_score: scores.composite_score || 5,
    score_reason: scores.score_reason || '',
    score_category: scores.score_category || articleData.category,
    source_count: articleData.source_count || 1,
    cluster_id: articleData.cluster_id,
    header_score: articleData.header_score,
    tags: articleData.tags
  }
}];

