const sc = s.source_count > 1 ? ' ('+s.source_count+' sources)' : '';
const trending = s.source_count >= 3 ? '🔥 Trending' + sc + '\n' : '';
return trending +
  '📊 ' + s.composite_score + '/10 — ' + s.score_category + '\n\n' +
  '<b>' + s.title + '</b>\n\n' +
  'R:' + s.relevance_score + ' N:' + s.novelty_score + ' X:' + s.cross_domain_score + '\n\n' +
  '<a href="' + s.url + '">Read article</a>';
})() }}
